use vstd::prelude::*;

verus! {

/// Returns an exact copy of the input vector `a`.  We assume
/// the input vector’s length is at most 100.
/// The result `b` has the same length as `a`, and
/// for every valid index `i`, `b[i] == a[i]`.
fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
    requires
        a.len() <= 100,
    ensures
        b.len() == a.len(),
    ensures
        forall |i: usize| i < a.len() ==> b[i] == a[i]
{
    let mut b: Vec<u64> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            b.len() == i,
            forall |j: usize| j < i ==> b[j] == a[j],
        decreases
            a.len() - i,
    {
        b.push(a[i]);
        i = i + 1;
    }
    b
}

}

